  'This foundational philosophy course trains students to reason carefully about moral truth, value, duty, character, justice, responsibility, and urgent applied dilemmas.',
  $ethmjson${"slug": "ethics-moral-philosophy", "title": "Ethics / Moral Philosophy", "description": "This foundational philosophy course trains students to reason carefully about moral truth, value, duty, character, justice, responsibility, and urgent applied dilemmas.", "topics": [{"id": "e688d8c6-38a1-46dd-bcf0-cfb0e9c75df8", "type": "topic", "title": "Philosophical Method, Moral Reasoning, and Normative Argument", "description": "Students learn how moral philosophy works as a discipline: clarifying concepts, testing principles, reading arguments charitably, and building reasons that can survive serious objections.", "children": [{"id": "1ff8289a-6b2d-455f-b30e-d97b8cdc3278", "type": "subtopic", "title": "What moral philosophy studies", "children": [{"id": "38bdfe44-2899-491f-91d4-4fd23f0c6b6e", "type": "concept", "title": "Normative ethics, applied ethics, metaethics, moral psychology, and political morality"}, {"id": "2e78d0ea-ca1d-440a-8a38-df1e40f73d86", "type": "concept", "title": "Actions, intentions, consequences, duties, virtues, rights, value, institutions, and character"}, {"id": "08240e56-1e6d-4406-8ae7-5e96515d9fe2", "type": "concept", "title": "Descriptive claims versus evaluative claims versus prescriptive claims"}], "description": "See ethics as more than personal opinion or rule memorization."}, {"id": "c6573541-d714-4130-8b83-ff54e6620d56", "type": "subtopic", "title": "Argument analysis", "children": [{"id": "71d05d97-cf1a-44d2-84c7-3904973637d1", "type": "concept", "title": "Premises, conclusions, hidden assumptions, validity, soundness, and counterexamples"}, {"id": "a9461f60-5004-4cbe-83e9-0a7f27c409af", "type": "concept", "title": "Principle testing, thought experiments, analogies, distinctions, and burden of proof"}, {"id": "49f7afdd-435b-4e8d-8db1-d5b5f07d7ff2", "type": "concept", "title": "Charitable interpretation, steelmanning, and avoiding straw-person readings"}], "description": "Reconstruct and test moral arguments with precision."}, {"id": "9f4e98b1-ed1e-49a0-b9be-ff40dda90f6c", "type": "subtopic", "title": "Philosophical writing", "children": [{"id": "2befccaf-7b2a-41e3-982d-f0a895cb75ef", "type": "concept", "title": "Thesis, roadmap, definitions, textual evidence, structured objections, and replies"}, {"id": "44461623-b042-4c05-9b90-ba789b1bf137", "type": "concept", "title": "Use of primary texts, secondary sources, citations, and fair quotation practice"}, {"id": "ab1c4b48-5d3f-4589-9ef5-48b5aa34167e", "type": "concept", "title": "Revision, peer review, argumentative clarity, and intellectual humility"}], "description": "Turn disagreement into a clear, disciplined written argument."}]}, {"id": "38f740a1-8cb7-42e8-bde4-f3c4c21181e1", "type": "topic", "title": "Moral Disagreement, Relativism, Objectivity, and Pluralism", "description": "This topic asks whether moral claims can be true, rationally defended, or cross-culturally criticized when people and traditions disagree deeply.", "children": [{"id": "4abb14de-545f-4893-b3f4-1c5db7b277d4", "type": "subtopic", "title": "Moral disagreement", "children": [{"id": "cf7a1e65-b701-4f55-9772-f834239b01e2", "type": "concept", "title": "Intrapersonal, interpersonal, cultural, historical, religious, and political disagreement"}, {"id": "84ba90c5-81c7-46fb-b994-ccc38402b0a1", "type": "concept", "title": "Disagreement about facts, values, concepts, rankings, and application to cases"}, {"id": "1ed134f8-63b7-4f4c-9225-dd2b492bc848", "type": "concept", "title": "Peer disagreement, humility, confidence, and rational revision"}], "description": "Understand why disagreement matters and why it does not automatically defeat moral knowledge."}, {"id": "433634c3-40d4-47e7-810b-454c39ecff5a", "type": "subtopic", "title": "Relativism and subjectivism", "children": [{"id": "07594158-ab9c-4ed7-814d-86f22fe95d14", "type": "concept", "title": "Individual subjectivism, cultural relativism, conventionalism, and moral skepticism"}, {"id": "41258776-c340-4c30-9ced-7922ffe27cdf", "type": "concept", "title": "Tolerance, imperialism, reform, criticism, moral progress, and internal dissent"}, {"id": "9c7e7c2c-81f5-4491-9bde-6e3db4216898", "type": "concept", "title": "Self-reference problems, disagreement within cultures, and cross-cultural judgment"}], "description": "Understand attractive and dangerous versions of the claim that morality is relative."}, {"id": "6f6a2860-addf-4104-a676-af05e469d7b6", "type": "subtopic", "title": "Pluralism and objectivity", "children": [{"id": "301c2560-ebd4-4398-9509-a5ba6c08e26e", "type": "concept", "title": "Value pluralism, moral uncertainty, tragic conflict, and incommensurable goods"}, {"id": "4b3d85e9-33b4-4e2c-a444-00c5229e3d61", "type": "concept", "title": "Objectivity without certainty, fallibilism, public reasons, and overlapping consensus"}, {"id": "21d5c4bb-36c6-4b57-b464-73f261e19ec2", "type": "concept", "title": "Respectful engagement across traditions, identities, and moral vocabularies"}], "description": "Examine whether moral truth can be objective while still allowing complexity."}]}, {"id": "29ac816b-8f20-4c80-ba18-ad7bb777714f", "type": "topic", "title": "Consequentialism, Utility, Welfare, and Moral Tradeoffs", "description": "Students study views that judge actions and institutions by outcomes, while learning how to evaluate aggregation, sacrifice, impartiality, and unintended consequences.", "children": [{"id": "3a7a00e7-857d-41c5-857e-eefc9fbb81b0", "type": "subtopic", "title": "Classical utilitarianism", "children": [{"id": "b9576293-e3e3-4398-beb5-d3efa60633b4", "type": "concept", "title": "Bentham, Mill, happiness, pleasure, pain, welfare, and impartial aggregation"}, {"id": "c9fa9bcd-9343-4d86-a555-ab5119629894", "type": "concept", "title": "Act utilitarianism, rule utilitarianism, expected utility, and cost-benefit reasoning"}, {"id": "96dc28d7-5a94-48d6-af12-581602db1830", "type": "concept", "title": "Demandingness, integrity, supererogation, and the separateness of persons"}], "description": "The core consequentialist idea that outcomes matter morally."}, {"id": "78193873-d88c-4b35-9aaa-091434cf09cc", "type": "subtopic", "title": "Consequences and measurement", "children": [{"id": "a115370c-7fb8-4c73-8fc4-9395daacfaef", "type": "concept", "title": "Hedonism, preference satisfaction, objective-list theories, capabilities, and flourishing"}, {"id": "b1c19e2d-6bb5-4b5c-aa79-b392cb3dc4ea", "type": "concept", "title": "Quantification, uncertainty, long-term effects, distribution, risk, and side effects"}, {"id": "89a11d7b-4512-498f-baf1-8281b1b14cf6", "type": "concept", "title": "Evidence, prediction, moral uncertainty, and precautionary reasoning"}], "description": "Ask what should count as a good outcome and how we could know."}, {"id": "5ecfbe65-d0cb-4f09-a271-375b217dce10", "type": "subtopic", "title": "Tradeoff cases", "children": [{"id": "0016ef7e-a73c-4ef3-902a-4cb4ea682b07", "type": "concept", "title": "Trolley cases, triage, punishment, policy tradeoffs, climate choices, and public health restrictions"}, {"id": "dfc8c1c4-fc1b-4349-84a4-0193b95c719a", "type": "concept", "title": "Rights objections, minority sacrifice, justice constraints, and moral side constraints"}, {"id": "4af3ab29-d628-4b52-99f1-ece38d8791d7", "type": "concept", "title": "Consequentialist replies, rule-based protections, and institutional design"}], "description": "Test consequentialism against cases where benefits and harms collide."}]}, {"id": "2e5fde0f-2806-4d85-a9bd-97f6e85c67f6", "type": "topic", "title": "Kantian Ethics, Deontology, Duties, and Respect for Persons", "description": "This module examines moral theories centered on duty, autonomy, universal law, dignity, and the wrongness of treating persons merely as means.", "children": [{"id": "968ec57b-53d2-4d19-a3cc-0be7b90986cb", "type": "subtopic", "title": "Good will and duty", "children": [{"id": "ca9ad6d6-5084-4fdb-a03a-ccd9c4d2012b", "type": "concept", "title": "Good will, duty, inclination, moral worth, autonomy, and practical reason"}, {"id": "bb4fe45a-9e17-4a0e-b4b7-2cea48862f4e", "type": "concept", "title": "Perfect duties, imperfect duties, duties to self, and duties to others"}, {"id": "8e7d76b5-19cf-4999-aad9-7f8a3308f94d", "type": "concept", "title": "Motive, intention, maxims, and acting from respect for moral law"}], "description": "Ground morality in rational agency rather than outcomes."}, {"id": "2d3957d4-709a-4fb8-b1b1-c344de4ecf44", "type": "subtopic", "title": "Categorical imperative", "children": [{"id": "5ada283a-c05a-436f-bceb-ec34b6fec277", "type": "concept", "title": "Universal law formulation, contradiction in conception, contradiction in will"}, {"id": "781bfaa4-aa79-4e74-8a02-d0300215a7e5", "type": "concept", "title": "Humanity formulation, persons as ends, dignity, consent, coercion, and manipulation"}, {"id": "e7f3c708-866a-4209-8fa7-42ff63369a7c", "type": "concept", "title": "Kingdom of ends, public law, consistency, and respect among rational agents"}], "description": "Test whether a maxim can be morally universalized."}, {"id": "18e03e8f-a521-4f2b-99a4-32663f490582", "type": "subtopic", "title": "Deontological dilemmas", "children": [{"id": "2807ac42-ba9b-49fa-9be1-f5e2968f2df9", "type": "concept", "title": "Lying, promises, punishment, privacy, exploitation, torture, and emergency cases"}, {"id": "5dc92d64-3283-4447-82ab-488f0c31360e", "type": "concept", "title": "Conflicting duties, threshold deontology, double effect, and moral residue"}, {"id": "b5254843-0610-4bb5-9515-bee60f4af6c2", "type": "concept", "title": "Critiques from consequentialism, care ethics, virtue ethics, and moral particularism"}], "description": "Examine the force and limits of duty-based ethics."}]}, {"id": "1a71d28b-9f79-44d5-8dc8-9fb349a946c5", "type": "topic", "title": "Virtue Ethics, Character, Flourishing, and Practical Wisdom", "description": "Students learn an agent-centered approach to ethics that asks what kind of person to become and how habits, emotions, and judgment support a good life.", "children": [{"id": "5951498e-7150-40f0-8bc4-6044b5af5759", "type": "subtopic", "title": "Aristotelian foundations", "children": [{"id": "c545c466-890c-4f15-8410-ea9075dfe6b9", "type": "concept", "title": "Eudaimonia, function argument, habituation, virtue, vice, and the mean"}, {"id": "a128582c-e69c-45df-830c-cbbca723a87c", "type": "concept", "title": "Courage, temperance, justice, generosity, truthfulness, friendship, and magnanimity"}, {"id": "fa29c64a-8b38-4de4-a466-b80de84ef3fd", "type": "concept", "title": "Role of community, education, law, models, and moral formation"}], "description": "Ethics as the cultivation of excellent character in a life aimed at flourishing."}, {"id": "31138f65-ab68-4000-aa06-cc466fd98649", "type": "subtopic", "title": "Practical wisdom", "children": [{"id": "c217b20d-affa-4fe2-beca-c86ece6dde27", "type": "concept", "title": "Phronesis, perception of salience, deliberation, timing, context, and experience"}, {"id": "35f8243b-2db7-495e-81f7-c2fa047b2885", "type": "concept", "title": "Moral exemplars, narrative identity, practices, and case-based learning"}, {"id": "098c873b-d10d-46d4-a148-e88f38b9dab1", "type": "concept", "title": "Conflicts among virtues, moral luck, weakness of will, and character development"}], "description": "Understand why ethical judgment cannot be reduced to a formula."}, {"id": "46a43a37-cd91-4f1d-8da2-c68a37c91bdb", "type": "subtopic", "title": "Contemporary virtue ethics", "children": [{"id": "88a3c11b-dc49-4d3b-bf4e-bec472b9824a", "type": "concept", "title": "Professional virtues, civic virtues, epistemic virtues, environmental virtues, and digital virtues"}, {"id": "901c38ed-4efc-433c-8ece-3408af430d10", "type": "concept", "title": "Care, humility, honesty, courage, compassion, justice, and practical responsibility"}, {"id": "aa4a870e-de0a-4793-b665-30c3d13f3921", "type": "concept", "title": "Critiques about action guidance, cultural specificity, elitism, and social injustice"}], "description": "Connect ancient virtue ethics to modern life and institutions."}]}, {"id": "58fa085d-d48a-457d-acf5-d192c76217bc", "type": "topic", "title": "Natural Law, Rights, Human Dignity, and Moral Limits", "description": "This topic explores moral constraints, rights, basic goods, human dignity, and the idea that some actions may be wrong even when they produce benefits.", "children": [{"id": "1e8fae2f-5518-4c93-863f-a43e786d55d9", "type": "subtopic", "title": "Natural law reasoning", "children": [{"id": "56ecf431-f208-489a-9524-96167f364184", "type": "concept", "title": "Aquinas, practical reason, basic goods, flourishing, law, conscience, and common good"}, {"id": "510d89f0-0600-4227-9675-a163491bb910", "type": "concept", "title": "Intention, side effects, double effect, proportionality, and intrinsically wrong acts"}, {"id": "a7169bea-e42f-452b-9403-596d888c9b15", "type": "concept", "title": "Contemporary natural law, secular versions, and major objections"}], "description": "Morality connected with human nature, reason, and basic goods."}, {"id": "efb10952-21b1-4aaa-a82c-8b643a325ee2", "type": "subtopic", "title": "Rights and dignity", "children": [{"id": "8d9d4f89-a64c-45da-9cad-025c767190cf", "type": "concept", "title": "Human rights, claim rights, liberty rights, positive rights, negative rights, and duties"}, {"id": "eda63b55-baa5-47bb-90ae-bf436726a08c", "type": "concept", "title": "Dignity, autonomy, bodily integrity, conscience, speech, privacy, and due process"}, {"id": "735e1841-8445-49df-b43d-1106c6e271a6", "type": "concept", "title": "Rights conflicts, limits, emergency powers, and institutional enforcement"}], "description": "Moral claims that protect persons against misuse or domination."}, {"id": "a9f00773-416d-4e37-b154-b4f568533984", "type": "subtopic", "title": "Moral limits", "children": [{"id": "f02e2c53-f106-4e87-953c-6d620b7006ba", "type": "concept", "title": "Torture, exploitation, commodification, killing, deception, and betrayal"}, {"id": "a81c22ae-169e-4f41-a717-c035b24d3e8a", "type": "concept", "title": "Doctrine of double effect, intention versus foresight, and moral thresholds"}, {"id": "1e8272e1-d760-4faa-9270-be91acfaf2d6", "type": "concept", "title": "Critiques from pluralism, consequentialism, feminist ethics, and political realism"}], "description": "Examine whether some actions are ruled out even in pursuit of good ends."}]}, {"id": "ad688cdc-d0af-4307-9635-a8b8988cf66e", "type": "topic", "title": "Contractualism, Social Contract Theory, Care Ethics, and Feminist Ethics", "description": "Students compare approaches that ground morality in justifiability to others, social cooperation, dependency, care, power, and relational responsibility.", "children": [{"id": "d126ed2d-1116-4c00-acf6-38fce52d688d", "type": "subtopic", "title": "Social contract traditions", "children": [{"id": "3ef63f00-72b5-4603-a1d1-d42902a885df", "type": "concept", "title": "Hobbes, Locke, Rousseau, Rawls, legitimacy, consent, reciprocity, and authority"}, {"id": "131272a8-23bd-42dc-ab42-e5cd9e103c84", "type": "concept", "title": "Original position, veil of ignorance, fairness, basic liberties, and difference principle"}, {"id": "417ce617-3146-4d3a-b638-01f76e7fa107", "type": "concept", "title": "Critiques involving exclusion, race, gender, disability, colonialism, and bargaining power"}], "description": "Ground morality and political obligation in fair cooperation."}, {"id": "75043ea7-177d-4913-ac22-f8e4f54e7284", "type": "subtopic", "title": "Contractualism", "children": [{"id": "897b58c6-3bd6-4c8c-80f5-ae0194976033", "type": "concept", "title": "Scanlon, justifiability to others, reasonable rejection, and moral complaint"}, {"id": "dae46eed-e8c8-49a5-b45f-1f2339a46adb", "type": "concept", "title": "Generic reasons, burdens, rescue, promises, aggregation, and interpersonal respect"}, {"id": "d51f5c5a-6a2d-45d1-84ce-2f3458b3f7f7", "type": "concept", "title": "Connections to rights, democracy, deliberation, and public justification"}], "description": "Identify principles no one could reasonably reject."}, {"id": "cacebcf9-f693-44ad-b302-f511804f3356", "type": "subtopic", "title": "Care and feminist ethics", "children": [{"id": "84caffcc-e176-430f-9aa5-b148c5479456", "type": "concept", "title": "Care, empathy, vulnerability, dependency, partiality, responsiveness, and repair"}, {"id": "ed72a74b-5cf0-49e4-b013-b9b5b6cdc738", "type": "concept", "title": "Critiques of abstract impartiality, atomistic persons, and gendered labor"}, {"id": "f2c8a690-e77d-460e-a19c-725922fcdc8b", "type": "concept", "title": "Intersectionality, standpoint, relational autonomy, oppression, and institutional care"}], "description": "Moral life through dependency, relationship, power, and social location."}]}, {"id": "54a74e96-cb55-4f93-876c-5f45374ef333", "type": "topic", "title": "Moral Psychology, Emotion, Motivation, Bias, and Moral Development", "description": "This module connects moral theory to human psychology: empathy, guilt, anger, character, cognitive bias, motivation, and the gap between judgment and action.", "children": [{"id": "b45c9463-1d06-4a85-bdfb-316e51f8f93e", "type": "subtopic", "title": "Moral emotions", "children": [{"id": "cd881167-3df2-47fb-ad90-5f9fc95fe531", "type": "concept", "title": "Empathy, compassion, guilt, shame, anger, resentment, disgust, gratitude, and admiration"}, {"id": "249327c7-09e8-4d31-8ab8-934ed2f101a6", "type": "concept", "title": "Sentimentalism, reason-emotion debates, emotional calibration, and moral perception"}, {"id": "71f50aa3-bc15-49c6-9eef-9b1d018ffdb8", "type": "concept", "title": "Anger and injustice, compassion fatigue, disgust bias, and empathy limits"}], "description": "How emotions can distort moral judgment but also disclose moral value."}, {"id": "86b1c898-7e45-402c-8902-12a8070d36c1", "type": "subtopic", "title": "Motivation and weakness", "children": [{"id": "abf5cfa4-2559-4e13-b37a-6b689a272eb0", "type": "concept", "title": "Internalism, externalism, akrasia, self-deception, rationalization, and habit"}, {"id": "8b9051f1-9873-4f41-a2c5-75ff44ca9a8e", "type": "concept", "title": "Moral identity, integrity, courage, social pressure, authority, and conformity"}, {"id": "277d866e-369d-4b83-9ce7-b0a45cf0dc04", "type": "concept", "title": "Designing environments that support ethical conduct and speaking up"}], "description": "Analyze why people fail to do what they judge right."}, {"id": "f0787096-e03f-4341-a751-0325cc149081", "type": "subtopic", "title": "Bias and development", "children": [{"id": "a18e9bd5-e72b-4bb4-a8a2-efc0b8a6963c", "type": "concept", "title": "Implicit bias, motivated reasoning, framing effects, group loyalty, and moral disengagement"}, {"id": "784d615a-d643-44ee-a586-d2d94552a38d", "type": "concept", "title": "Kohlberg, Gilligan, social intuitionism, virtue formation, and moral education"}, {"id": "a18f878a-c232-457f-8caf-e342efefda12", "type": "concept", "title": "Debiasing, reflection, accountability partners, institutional checks, and humility"}], "description": "Ethical reasoning as it relates to cognitive bias, character formation, and growth."}]}, {"id": "deacf0e1-2a10-4f0f-85e2-04f15c279a07", "type": "topic", "title": "Freedom, Moral Responsibility, Praise, Blame, and Accountability", "description": "Students investigate what makes a person responsible and how ignorance, coercion, luck, character, social conditions, and institutions affect blame and accountability.", "children": [{"id": "44825ca7-64b5-4625-b2e5-1a697cf0576c", "type": "subtopic", "title": "Free will and responsibility", "children": [{"id": "afbef559-2eb4-4935-a36e-627b9ead660d", "type": "concept", "title": "Determinism, libertarianism, compatibilism, hard incompatibilism, and agency"}, {"id": "2ad4ebce-6882-49f6-9c97-7df908a3e66b", "type": "concept", "title": "Reasons-responsiveness, control, alternatives, sourcehood, and manipulation cases"}, {"id": "b6d4d0e1-39f9-4805-b04c-8944b8491fb1", "type": "concept", "title": "Neuroscience, psychology, addiction, coercion, and social constraint"}], "description": "Explore whether responsibility requires freedom and what kind of freedom matters."}, {"id": "a94f967e-a105-47ff-bb66-727b13c3dcfa", "type": "subtopic", "title": "Praise and blame", "children": [{"id": "59092488-b02f-4b19-bec8-9ddd7c3845bb", "type": "concept", "title": "Strawson, reactive attitudes, resentment, gratitude, forgiveness, and excuse"}, {"id": "08aad369-6b58-49bd-b6dd-8002173eb732", "type": "concept", "title": "Ignorance, negligence, recklessness, mens rea, moral luck, and culpability"}, {"id": "85ad54dd-0e79-44be-92c9-474ff0bf19de", "type": "concept", "title": "Blameworthiness, shame, apology, repair, reconciliation, and restorative practices"}], "description": "Moral accountability as a practice, not merely a verdict."}, {"id": "f0f5707c-eac7-4201-a73b-65c97b844a38", "type": "subtopic", "title": "Institutional accountability", "children": [{"id": "75d011ea-d8d0-4d50-80ba-3d711e9c19b1", "type": "concept", "title": "Collective responsibility, complicity, structural injustice, role responsibility, and command responsibility"}, {"id": "68619a83-50d4-4ea2-a70f-882b10b45279", "type": "concept", "title": "Corporations, governments, universities, professions, platforms, and distributed harms"}, {"id": "ef29f1b2-2463-4cbd-8e97-9812b5025ec2", "type": "concept", "title": "Accountability mechanisms, transparency, sanctions, remediation, and institutional learning"}], "description": "Analyze responsibility for groups, organizations, and systems."}]}, {"id": "83d677ef-50f3-456a-a652-4d46354e0e1d", "type": "topic", "title": "Justice, Equality, Rights, Liberty, and Political Morality", "description": "This topic links moral philosophy with political philosophy by examining fairness, rights, authority, coercion, distribution, democracy, punishment, and global justice.", "children": [{"id": "a130a949-ebf5-4e3b-b4ea-22bd5d79d971", "type": "subtopic", "title": "Theories of justice", "children": [{"id": "263e4d03-5874-4038-b8b0-2a6abcd663c8", "type": "concept", "title": "Rawlsian justice, utilitarian justice, libertarianism, luck egalitarianism, capabilities, and sufficientarianism"}, {"id": "1017c77a-2a14-42bb-a7c9-a75ec1c17006", "type": "concept", "title": "Fair equality of opportunity, distributive justice, desert, need, merit, and reciprocity"}, {"id": "9bd7dc07-3a89-45a2-9a40-d98182959548", "type": "concept", "title": "Structural injustice, historical injustice, reparations, and social membership"}], "description": "Frameworks for evaluating social institutions and distributions."}, {"id": "99a2600f-7d75-47c2-ab0a-e66cb8912419", "type": "subtopic", "title": "Liberty, authority, and coercion", "children": [{"id": "0212375c-7205-4311-9e76-803a44a3d172", "type": "concept", "title": "Consent, legitimacy, state authority, civil disobedience, paternalism, and harm principle"}, {"id": "beffe10e-369f-436f-b5c7-3b36daef252f", "type": "concept", "title": "Freedom of expression, privacy, association, religion, bodily autonomy, and due process"}, {"id": "631843eb-c23b-4dcd-be6d-0be7406ff949", "type": "concept", "title": "Punishment, policing, surveillance, emergency powers, and democratic accountability"}], "description": "Evaluate when law and institutions may legitimately restrict freedom."}, {"id": "16140f90-487d-4be3-9f05-8b799156ca85", "type": "subtopic", "title": "Global and intergenerational justice", "children": [{"id": "7b1ad904-9d6f-4b27-8963-7c5aaf2f0833", "type": "concept", "title": "Global poverty, migration, war, human rights, climate justice, and development"}, {"id": "748398ac-a777-48dc-974a-77064a108351", "type": "concept", "title": "Duties to future generations, sustainability, discounting, and planetary boundaries"}, {"id": "a37b9fcc-182e-40c9-98b8-6f414849b304", "type": "concept", "title": "Cosmopolitanism, nationalism, postcolonial critique, and international institutions"}], "description": "Justice beyond national borders and present generations."}]}, {"id": "470d0d0c-2171-4d53-9734-0cef3d4c9eed", "type": "topic", "title": "Applied Ethics: Life, Health, Environment, Animals, Technology, and AI", "description": "Students apply moral theories to urgent cases where real decisions involve uncertainty, power, competing values, and institutional consequences.", "children": [{"id": "0c5b7e6c-b633-4a21-b3f7-c1b4ed0a34b9", "type": "subtopic", "title": "Bioethics and health ethics", "children": [{"id": "02796e6c-6b1e-4f6f-8b74-5d8723b77e57", "type": "concept", "title": "Autonomy, informed consent, beneficence, nonmaleficence, justice, and confidentiality"}, {"id": "012436af-5439-44f1-9370-371440d81a2b", "type": "concept", "title": "Abortion, euthanasia, disability, organ allocation, triage, research ethics, and public health restrictions"}, {"id": "65337f60-2eaa-42dc-9457-3d22dfb1d675", "type": "concept", "title": "Individual rights versus common good, equity, vulnerability, and professional responsibility"}], "description": "Apply principles to life, death, medicine, and public health."}, {"id": "db336d8b-55c3-4b52-b354-2fd14a76d7d1", "type": "subtopic", "title": "Environmental and animal ethics", "children": [{"id": "d4a8c34f-b38b-4e14-9266-5a4cfefa1752", "type": "concept", "title": "Anthropocentrism, sentience, biocentrism, ecocentrism, land ethic, and deep ecology"}, {"id": "b1353fdf-c966-400c-a4a2-0974d6af7fc7", "type": "concept", "title": "Animal welfare, animal rights, speciesism, food systems, conservation, and biodiversity"}, {"id": "261f8d28-73b9-43d2-86ce-78b875921720", "type": "concept", "title": "Climate ethics, environmental justice, sustainability, loss and damage, and future generations"}], "description": "Question moral standing for non-human entities."}, {"id": "eb365bb8-a4a7-4995-8a03-d56c2094af66", "type": "subtopic", "title": "Technology and AI ethics", "children": [{"id": "7e1f2e99-a9a4-4b83-93db-ed92c46ea596", "type": "concept", "title": "Privacy, surveillance, algorithmic bias, transparency, accountability, autonomy, and manipulation"}, {"id": "0a385310-6187-4062-89c5-d4513c94ed02", "type": "concept", "title": "AI alignment, explainability, data consent, platform design, labor displacement, and misinformation"}, {"id": "bbaa2d23-d17b-4dfa-950b-1e16fb1f673a", "type": "concept", "title": "Professional codes, regulation, precaution, stakeholder impact, and responsible innovation"}], "description": "Evaluate new tools through moral questions."}]}, {"id": "205a46db-1aa5-45e1-8270-d31de40e646d", "type": "topic", "title": "Professional, Business, Public, and Institutional Ethics", "description": "This module studies ethical decision-making inside organizations, professions, governments, markets, and institutions where incentives and accountability structures shape conduct.", "children": [{"id": "2d66d7fd-ae2a-489e-af49-6794e3efe030", "type": "subtopic", "title": "Business and organizational ethics", "children": [{"id": "4c63dd40-493d-4517-a92e-0418a8a4261e", "type": "concept", "title": "Shareholder theory, stakeholder theory, CSR, ESG, greenwashing, and corporate accountability"}, {"id": "1ea2b55c-b2dc-443c-a411-2cf6c7a8ea6f", "type": "concept", "title": "Conflicts of interest, incentives, compliance systems, boards, culture, and misconduct prevention"}, {"id": "ee7132a5-e5ac-4083-a862-f061a06a2782", "type": "concept", "title": "Whistleblowing, retaliation, crisis response, reputation recovery, and ethical leadership"}], "description": "Moral problems inside firms and markets."}, {"id": "a7d2f0f7-3fb9-4276-8200-3d6027838e6e", "type": "subtopic", "title": "Public ethics", "children": [{"id": "28aad7da-f6ab-4165-8a09-7bd4461ced59", "type": "concept", "title": "Legitimacy, transparency, impartiality, discretion, due process, and administrative burden"}, {"id": "dfc1f622-8bbe-49dc-b14f-a3c1f0ec8eef", "type": "concept", "title": "Corruption, capture, gifts, conflicts of interest, public accountability, and oversight"}, {"id": "3818ae67-883a-4d92-aeee-0043b42e3047", "type": "concept", "title": "Equity impact assessment, procedural justice, community participation, and democratic values"}], "description": "Ethics in roles of public power and public trust."}, {"id": "0b76381f-a38e-4e97-83ef-0f216dcec7e4", "type": "subtopic", "title": "Professional ethics", "children": [{"id": "5649c388-9946-4620-aeac-2a8b71ec93c9", "type": "concept", "title": "Law, medicine, accounting, engineering, education, social work, research, and journalism"}, {"id": "fa716908-43a3-4bcc-a39d-7e5407683e9d", "type": "concept", "title": "Confidentiality, competence, independence, informed consent, client loyalty, and public interest"}, {"id": "3c5902e2-8f35-4b88-947c-e24182141133", "type": "concept", "title": "Code-based reasoning, professional judgment, moral distress, and conscientious refusal"}], "description": "Role morality and professional codes in judgment."}]}, {"id": "6dde0c48-abf5-45d5-86bc-b83bc10df1f7", "type": "topic", "title": "Comparative, Religious, Cross-Cultural, and Global Ethics", "description": "Students learn to engage moral reasoning across traditions while avoiding both shallow relativism and dismissive universalism.", "children": [{"id": "8627b74c-3c4c-484c-b49e-fceb75a09237", "type": "subtopic", "title": "Sources of moral authority", "children": [{"id": "3affc9ea-5c1f-49e9-8d23-bd244579f729", "type": "concept", "title": "Reason, scripture, revelation, law, tradition, community, conscience, nature, and lived practice"}, {"id": "5a0c8d07-e27f-44f4-a65e-50740fca1df2", "type": "concept", "title": "Virtue, command, compassion, justice, liberation, covenant, dharma, and harmony"}, {"id": "f39fa21b-6db0-43ca-9650-4b3e04e67eaf", "type": "concept", "title": "Interpretation, authority, reform, dissent, pluralism, and moral learning across traditions"}], "description": "How traditions justify moral claims differently."}, {"id": "01c390f4-16fa-40fb-8fc9-fe5588a51100", "type": "subtopic", "title": "Comparative case analysis", "children": [{"id": "0855d068-6a92-47bf-a593-3e4f3a8d444f", "type": "concept", "title": "Poverty, war and peace, sexuality, family, gender, bioethics, environment, and human rights"}, {"id": "740380fd-c721-462a-8012-64e57833bf3c", "type": "concept", "title": "Internal diversity, majority/minority voices, colonial context, and contemporary practice"}, {"id": "61ba23d2-8cd3-4855-9089-36f6df294ad8", "type": "concept", "title": "Translation problems, respectful critique, and shared practical reasoning"}], "description": "Compare traditions carefully without flattening differences."}, {"id": "8bb9f68c-b1d1-4bdc-813b-84888786a63e", "type": "subtopic", "title": "Global ethics", "children": [{"id": "5631479f-e0af-47f8-8ff8-c18941bb0b98", "type": "concept", "title": "Human rights, humanitarian intervention, development, migration, trade, climate, and global health"}, {"id": "06b7b230-528f-4a91-8d43-4c1f224a1f90", "type": "concept", "title": "Cosmopolitanism, nationalism, pluralism, sovereignty, and global governance"}, {"id": "2e9d7131-dbd8-4b4d-9726-e2c131de8f79", "type": "concept", "title": "Moral risk in cross-cultural aid, advocacy, research, and policy design"}], "description": "Connect moral philosophy to transnational responsibilities."}]}, {"id": "935ba529-4279-4b93-9f3e-fa0a21f37ce0", "type": "topic", "title": "Metaethics, Moral Language, Value, and Reasons", "description": "This topic introduces deeper questions about moral facts, value, reasons, obligation, expressivism, realism, constructivism, and the meaning of moral language.", "children": [{"id": "50137d36-08ba-44b6-9c3d-cdce343e7da9", "type": "subtopic", "title": "Moral realism and anti-realism", "children": [{"id": "be8c24cd-e149-43bd-b4b9-a42b6b3137af", "type": "concept", "title": "Realism, naturalism, nonnaturalism, error theory, expressivism, constructivism, and quasi-realism"}, {"id": "15f244bc-4922-4206-aefd-6b7cec3e22da", "type": "concept", "title": "Objectivity, disagreement, moral knowledge, moral explanation, and queerness arguments"}, {"id": "fdf6233c-4c8a-450e-83d2-730aea83a431", "type": "concept", "title": "How metaethical views affect confidence, humility, and argument strategy"}], "description": "Ask whether moral claims report facts, express attitudes, or construct standards."}, {"id": "d08c5ac7-b08a-42cc-992d-c782a89dd016", "type": "subtopic", "title": "Value and reasons", "children": [{"id": "2e6cad34-b337-4abb-9d6c-fd48a255e892", "type": "concept", "title": "Intrinsic value, instrumental value, final value, fitting attitudes, and buck-passing accounts"}, {"id": "9db90851-ee94-48f4-baf9-d13d5efdd79a", "type": "concept", "title": "Reasons for action, reasons for belief, agent-neutral reasons, agent-relative reasons, and obligations"}, {"id": "27cf489a-4560-4b11-8d3b-dd28ebb87f8d", "type": "concept", "title": "Desire, rationality, well-being, normativity, and practical deliberation"}], "description": "Understand what makes something matter and what counts in favor of action."}, {"id": "7223fb9b-f736-456d-8825-21950b7ac963", "type": "subtopic", "title": "Moral language", "children": [{"id": "9555efaf-be08-4440-ab54-19e41d3a0158", "type": "concept", "title": "Good, right, wrong, ought, duty, virtue, reason, blame, justice, and harm"}, {"id": "c33ee6fa-2e19-4786-b8f4-1d6e19db2e16", "type": "concept", "title": "Open-question argument, is-ought gap, thick concepts, evaluative language, and disagreement"}, {"id": "58798c0d-567c-4bb6-8cf0-e89df0fb1368", "type": "concept", "title": "Conceptual analysis, ordinary language, genealogy, and moral critique"}], "description": "How the meaning of moral words shapes philosophical debates."}]}, {"id": "206e7454-eba5-40dd-9b6e-dd119e00420b", "type": "topic", "title": "Capstone: Ethical Case Analysis and Philosophical Argument Portfolio", "description": "Students synthesize the course by analyzing a hard case, defending a normative position, responding to objections, and revising a polished philosophical argument.", "children": [{"id": "55fe2ba8-f607-483f-af0d-99286ee94805", "type": "subtopic", "title": "Case selection and framing", "children": [{"id": "da59c80e-84ce-43ed-bacd-47726bad65ec", "type": "concept", "title": "Stakeholders, facts, uncertainty, institutional context, harms, benefits, duties, and power"}, {"id": "60580706-f5ff-4efe-ac80-f85e2bbb1b9f", "type": "concept", "title": "Normative question, competing values, relevant theories, and decision criteria"}, {"id": "5eaab334-c739-4726-84e2-16239746c80f", "type": "concept", "title": "Source gathering, case chronology, assumptions, and limits of analysis"}], "description": "Turn a messy real problem into a philosophically tractable question."}, {"id": "2456b408-c96f-4e0a-8d1c-0597877caf5f", "type": "subtopic", "title": "Argument construction", "children": [{"id": "ebeff241-1840-4ed5-a26e-16fda8114d8e", "type": "concept", "title": "Thesis, principle, application, supporting reasons, examples, and textual engagement"}, {"id": "14fc266e-405d-4edd-b07b-3087fe0e81d9", "type": "concept", "title": "Objections from rival theories, hard cases, counterexamples, and revised principles"}, {"id": "ac035574-8151-4bd2-83c9-5f5e954ae545", "type": "concept", "title": "Reply strategy, concession, distinction, reflective equilibrium, and final judgment"}], "description": "Defend a position that is clear, rigorous, and responsive to alternatives."}, {"id": "cb9ed92f-93ef-433c-a594-5bb6b54c7d5b", "type": "subtopic", "title": "Portfolio and presentation", "children": [{"id": "84e62ca9-fc58-4de3-b119-4cb6fd81cf53", "type": "concept", "title": "Analytic essay, case memo, annotated bibliography, revision note, and oral defense"}, {"id": "a35cb0bf-733a-4a54-bc1c-c783e336d7d6", "type": "concept", "title": "Peer workshop, presentation, question handling, and professional dialogue norms"}, {"id": "b317b9a2-00a3-401f-8558-515663e3318b", "type": "concept", "title": "Final reflection on moral uncertainty, intellectual humility, and responsible action"}], "description": "Philosophical communication for academic and public audiences."}]}], "dbBacked": true}$ethmjson$::jsonb,
